import{_ as r,o as t,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const i=JSON.parse('{"title":"德望学校 · 2020-21年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-4b0457f5","school_zh":"德望学校","school_en":"—","grade":"s1","year":"2020-21","year_label":"2020-21年度","type":"interview","title":"德望学校 · 2020-21年度 · 中一 · 面试","anonymous":true,"source_ids":["C1821-GHS-2021-FIRST","C1821-GHS-2021-MATH","C1821-GHS-2021-PRIMARY","C1821-GHS-2021-SECOND"],"rounds":["r1","unknown","r2"]},"headers":[],"relativePath":"reports/school-4b0457f5/s1/2020-21-interview.md","filePath":"reports/school-4b0457f5/s1/2020-21-interview.md"}'),a={name:"reports/school-4b0457f5/s1/2020-21-interview.md"};function p(n,o,c,g,l,h){return t(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="德望学校-·-2020-21年度-·-中一-·-面试" tabindex="-1">德望学校 · 2020-21年度 · 中一 · 面试 <a class="header-anchor" href="#德望学校-·-2020-21年度-·-中一-·-面试" aria-label="Permalink to &quot;德望学校 · 2020-21年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-4b0457f5">← 返回德望学校资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-ghs-2021-first" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-ghs-2021-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-ghs-2021-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>按人数分配小组时间</strong></p><p>一组规则为4人讨论6分钟、3人4.5分钟、2人3分钟、单人短讲1.5分钟；另有3名学生、2位老师，先3分钟准备再4.5分钟讨论。</p><p><strong>迎新、阅读与减功课</strong></p><p>作为成长组成员，为中一迎新设计活动及说明原因；作为阅读大使，建议提升阅读兴趣的活动；若中文删减一项功课，会删哪份及原因。一组原以为另有个人短讲，实际讨论后结束，不能把两部分都列为人人必经。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>每人一分钟不同题目</strong></p><p>同组各获不同话题，约1分钟短讲：喜欢的书、新年如何令人兴奋、卡通对童年的重要性、新学一项运动会选什么及原因。另一组比较校服与便服、在哪里最适合交朋友、肯德基与麦当劳哪家更好。</p><p><strong>边朗读边补词</strong></p><p>朗读英文文章，同时补上空缺单词，多涉及时态。</p></blockquote><blockquote><p><strong>数学：</strong> 英语</p><p><strong>网上测验及技术延迟</strong></p><p>先看规则与操作示范，再按电邮链接输入考生资料进入。考生反馈约11分钟20题，为小五至小六程度；部分场次出现技术问题，有人等约1小时才开始，也有人获告知另作安排。等候时间不计入正式测验时长。</p></blockquote><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>音乐专长：</strong> 英语</p><p><strong>演奏影片附加问卷</strong></p><p>提交乐器演奏片时填表，说明乐团或合奏经验、独奏经历、音乐强项、可如何为学校作贡献，以及音乐怎样丰富自己的生活。</p></blockquote><h2 id="record-c1821-ghs-2021-math" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-ghs-2021-math" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-ghs-2021-math}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>数学：</strong> 英语</p><p><strong>方向与图形位置</strong></p><p>20道选择题中，第1题为地图方位：正方形四角依次为左上LOVE、右上HOPE、右下JOY、左下THANKSGIVING，GHS在对角线交点；北箭头朝图面右下，问GHS位于THANKSGIVING的北、东、南还是西。</p><p><strong>数字规律与数表</strong></p><p>三角形外侧左、右、下三个数与中央数：1、2、3对应9，5、7、2对应24，问号、3、5对应25，选项2、3、4、5。数列450、641、832、1023之后填什么，选项1214、1254、1316、1354。另有1、2、2、4、3、8、4、问号，选项6、8、12、16。</p><p><strong>圆盘、平方表与数字塔</strong></p><p>八等分圆盘从左上开始顺时针为6、2、3、15、18、6、问号、5，选项15、4、9、16。两行表第一行为1、3、5、7，第二行为1、问号、25、49，选项9、13、17、21。数字塔示例底层7、5、6，中层12、11，顶层23；另一塔底层6、5、问号，顶层20，选项1、2、4、8。</p><p><strong>平均数、分数与递减重量</strong></p><p>中文60分、数学95分，若中英数平均75分，英语多少分（70、75、80、85）？零用钱的3/5买书、1/4买玩具，合共花掉百分之几（35%、70%、75%、85%）？五个俄罗斯套娃最大800克，每个较前一个减半，最小多少克（25、50、75、100）？</p><p><strong>相交圆与边框规律</strong></p><p>a、b、c、d为1至4四个不同正整数。外圈为0、1、d、a，内圈为3、2、c、b；两条交叉直线为0—3—c—d及1—2—b—a，每圈及每条线总和均为8。判断哪项必对：a+c=5、b与d相差2、b×c=3、a÷c=1。另有数字边框：顶边2、3、19、68、47、5；左边自上而下2、74、98、3、65、1；右边5、41、26、9、78、问号；底边左至右1、72、46、9、58、问号，缺数选3、4、5、6。</p><p><strong>空间与图形推理</strong></p><p>其余包括数堆叠立方体（选15、16、17、18）、九宫格涂色规律、线段符号异类判断、多种几何图形序列、比较四幅组合图中三角形数、圆弧组合规律、由三个骰子视图选展开图，以及蓝绿方格图案变换。骰子三个视图的上／前／右面分别为3／4／6、2／1／6、5／2／6。</p></blockquote><h2 id="record-c1821-ghs-2021-primary" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-ghs-2021-primary" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-ghs-2021-primary}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 小学升中面试</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-2" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-2" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>个人问答：</strong> 语言未注明；含英语</p><p><strong>校园与生活喜好</strong></p><p>最常使用哪项学校设施、觉得哪个校园地点最有趣、最喜欢的节日或香港地点；其中节日题为英语。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 语言未注明</p><p><strong>科目与手机</strong></p><p>若小六增设一科想加什么，是否认同体育课比电脑课好，以及应否带手机上学。</p></blockquote><h2 id="record-c1821-ghs-2021-second" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-ghs-2021-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-ghs-2021-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>学生面谈：</strong> 英语</p><p><strong>升中目标与学习困难</strong></p><p>入学后希望成为怎样的人、预计有什么困难；是否自行温习、曾否遇阻或成绩下降、怎样改善。另比较单簧管与游泳的喜好。</p><p><strong>旅行经历</strong></p><p>疫情前原有什么出国计划、曾到哪些地方、最难忘哪次，以及疫情后想去哪里。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>挑战、支持与科目强项</strong></p><p>对学校的期望、女儿升中的最大挑战、曾遇什么学习困难及如何克服、哪科较强。</p></blockquote>',33)])])}const b=r(a,[["render",p]]);export{i as __pageData,b as default};
